def merge_intervals(intervals):
    if not intervals:
        return []
    # Validate every interval before processing.
    for interval in intervals:
        if (not isinstance(interval, (list, tuple))
                or len(interval) != 2
                or not isinstance(interval[0], int)
                or not isinstance(interval[1], int)):
            raise ValueError("invalid interval")
        if interval[0] > interval[1]:
            raise ValueError("invalid interval")
    values = sorted([list(i) for i in intervals])
    out = [values[0][:]]
    for start, end in values[1:]:
        if start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def merge_intervals(intervals):
    if not intervals:
        return []
    # Validate all intervals first: each is [start,end] with integers and start<=end
    for interval in intervals:
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValueError('invalid interval')
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid interval')
        if start > end:
            raise ValueError('invalid interval')
    values = sorted(intervals)
    # Convert to fresh lists to avoid mutating input
    out = [list(values[0])]
    for start, end in values[1:]:
        if start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def largest_remainder(total, weights):
    if total < 0 or any(w < 0 for w in weights):
        raise ValueError("negative")
    weights = list(weights)
    s = sum(weights)
    if total > 0 and s == 0:
        raise ValueError("zero")
    if s == 0:
        return [0] * len(weights)
    raw = [total * w / s for w in weights]
    floors = [int(x) for x in raw]
    remainders = [(raw[i] - floors[i], i) for i in range(len(weights))]
    remaining = total - sum(floors)
    remainders.sort(key=lambda t: (-t[0], t[1]))
    result = list(floors)
    for k in range(remaining):
        result[remainders[k][1]] += 1
    return result

def dedupe_events(events):
    chosen = {}
    order = []
    for event in events:
        eid = event["id"]
        if eid not in chosen or event["seq"] >= chosen[eid]["seq"]:
            if eid not in chosen:
                order.append(eid)
            chosen[eid] = event
    selected = [(chosen[eid], idx) for idx, eid in enumerate(order)]
    selected.sort(key=lambda item: (item[0]["seq"], item[1]))
    return [dict(event) for event, _ in selected]

def dedupe_events(events):
    chosen = {}
    for event in events:
        eid = event["id"]
        if eid not in chosen or event["seq"] >= chosen[eid]["seq"]:
            chosen[eid] = event
    result = [dict(event) for event in chosen.values()]
    result.sort(key=lambda e: e["seq"])
    return result

def apply_edits(text, edits):
    n = len(text)
    # Validate all edits first: integer bounds, no overlap (half-open intervals).
    for edit in edits:
        start, end = edit["start"], edit["end"]
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError
        if not (0 <= start <= end <= n):
            raise ValueError
    # Sort edits by start position and check for overlaps among adjacent whitespaces.
    ordered = sorted(edits, key=lambda e: e["start"])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        cur = ordered[i]
        if cur["start"] < prev["end"]:
            raise ValueError
    # Apply edits simultaneously relative to original text: construct segments.
    parts = []
    pos = 0
    for edit in ordered:
        start, end = edit["start"], edit["end"]
        parts.append(text[pos:start])
        parts.append(edit["replacement"])
        pos = end
    parts.append(text[pos:])
    return "".join(parts)

def quorum_decision(votes, quorum):
    if quorum <= 0:
        raise ValueError("quorum")
    try:
        participation = 0
        yes = 0
        no = 0
        for v in votes:
            if v == "yes":
                yes += 1
            elif v == "no":
                no += 1
            elif v == "abstain":
                pass
            else:
                raise ValueError("vote")
            if v != "abstain":
                participation += 1
    except TypeError:
        raise ValueError("vote")
    if participation < quorum:
        return "no-quorum"
    if yes > no:
        return "yes"
    if no > yes:
        return "no"
    return "tie"

def quorum_decision(votes, quorum):
    if not isinstance(quorum, int) or quorum <= 0:
        raise ValueError("quorum")
    yes = 0
    no = 0
    for v in votes:
        if v == "yes":
            yes += 1
        elif v == "no":
            no += 1
        elif v == "abstain":
            continue
        else:
            raise ValueError("invalid vote")
    participation = yes + no
    if participation < quorum:
        return "no-quorum"
    if yes > no:
        return "yes"
    if no > yes:
        return "no"
    return "tie"
